from z3 import *

# Social Golfers: 24 golfers, 4 weeks, 6 groups of 4
num_weeks = 4
num_golfers = 24
num_groups = 6
group_size = 4

# x[w][p] = group of golfer p in week w (0..5)
x = [[Int(f"x_{w}_{p}") for p in range(num_golfers)] for w in range(num_weeks)]

s = Solver()

# Domain constraints
for w in range(num_weeks):
    for p in range(num_golfers):
        s.add(x[w][p] >= 0, x[w][p] < num_groups)

# Each group has exactly 4 golfers each week
for w in range(num_weeks):
    for g in range(num_groups):
        s.add(Sum([If(x[w][p] == g, 1, 0) for p in range(num_golfers)]) == group_size)

# No pair of golfers in the same group more than once
for p1 in range(num_golfers):
    for p2 in range(p1+1, num_golfers):
        # Count how many weeks they're in the same group
        same_group_count = Sum([If(x[w][p1] == x[w][p2], 1, 0) for w in range(num_weeks)])
        s.add(same_group_count <= 1)

print("Solving...")
result = s.check()
print(f"Result: {result}")

if result == sat:
    m = s.model()
    solution = []
    for w in range(num_weeks):
        for p in range(num_golfers):
            solution.append(m[x[w][p]].as_long())
    print(f"Solution: {solution}")
    print(f"Length: {len(solution)}")

    # Verify solution
    print("\nVerification:")
    for w in range(num_weeks):
        groups = [[] for _ in range(num_groups)]
        for p in range(num_golfers):
            groups[solution[w*24+p]].append(p)
        for g in range(num_groups):
            print(f"  Week {w}, Group {g}: {sorted(groups[g])}")

    # Check pair constraint
    pair_count = {}
    for w in range(num_weeks):
        for g in range(num_groups):
            members = [p for p in range(num_golfers) if solution[w*24+p] == g]
            for i in range(len(members)):
                for j in range(i+1, len(members)):
                    pair = (min(members[i], members[j]), max(members[i], members[j]))
                    pair_count[pair] = pair_count.get(pair, 0) + 1

    violations = [p for p, c in pair_count.items() if c > 1]
    print(f"\nPairs appearing more than once: {len(violations)}")
    if violations:
        print(f"Violations: {violations[:10]}")
else:
    print("UNSATISFIABLE")
